() => {
  const st = document.getElementById('stage');
  const r = st.getBoundingClientRect();
  const kids = [...st.children].map(k => ({c:k.className, t:+k.getBoundingClientRect().top.toFixed(1), h:+k.getBoundingClientRect().height.toFixed(1)}));
  // overflow check
  const over = [];
  st.querySelectorAll('*').forEach(e=>{
    if(e.scrollWidth - e.clientWidth > 1) over.push(e.className+' sw'+e.scrollWidth+' cw'+e.clientWidth);
  });
  const f = document.fonts.check('700 64px Inter');
  return {stage:[r.width,r.height], kids, over, fontLoaded:f, docScroll:[document.documentElement.scrollWidth, document.documentElement.scrollHeight]};
}

